mapper.sql:
SELECT A.* FROM ( SELECT B.ATCL_ID , B.UP_ATCL_ID , A.BBS_ID , B.HDR_TYCD , B.ATCL_TTL , B.ATCL_CTS , B.ATCL_LV , B.ATCL_SEQNO , B.PROC_STSCD , B.ATHR_ID , B.INQ_CNT , B.FVRT_CNT , B.DSCSN_PROF_ID , B.RGTR_ID , B.RGTRNM , B.REG_DTTM , B.MDFR_ID , B.MOD_DTTM , A.BBSNM , A.ATFL_USEYN , CASE WHEN A.ATFL_USEYN = 'Y' THEN (SELECT COUNT(1) FROM TB_LMS_ATFL WHERE ATCL_ID = B.ATCL_ID) ELSE 0 END AS ATFL_MAX_CNT , CASE WHEN EXISTS (SELECT 1 FROM TB_LMS_BBS WHERE UP_ATCL_ID = B.ATCL_ID AND DELYN = 'N') THEN 'Y' ELSE 'N' END AS ANSWER_YN , CASE WHEN A.REG_DTTM > FN_DTTM_SUB(7) THEN 'Y' ELSE 'N' END AS IS_NEW , (SELECT COUNT(1) FROM TB_LMS_BBS_ATCL_CMNT XX WHERE XX.ATCL_ID IN (SELECT ATCL_ID FROM TB_LMS_BBS_ATCL WHERE UP_ATCL_ID = B.ATCL_ID)) AS CMNT_CNT FROM TB_LMS_BBS A JOIN TB_LMS_BBS_ATCL B ON A.BBS_ID = B.BBS_ID AND A.DELYN = 'N' AND A.ORG_ID = #{orgId} AND A.DELYN = 'N' AND A.BBS_ID = #{bbsId}
AND A.BBS_ID IN (
#{item}
)
AND A.SBJCT_ID = #{crsCreCd} AND EXISTS ( SELECT 1 FROM TB_HOME_BBS_RLTN WHERE BBS_ID = A.BBS_ID AND RLTN_REF_CD = A.SBJCT_ID AND CONTS_TYCD = 'COURSE' )
AND LOWER(A.ATCL_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
AND LOWER(A.RGTRNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
AND ( LOWER(A.ATCL_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(A.RGTRNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
) A

