mapper.select:
/* SQL ID : BbsAtclDAO.listDeclsBbsAtcl 설 명 : 분반 게시글 정보 목록 */ SELECT A.* FROM ( SELECT A.BBS_ID , A.ATCL_ID , A.SBJCT_ID , (SELECT SBJCTNM FROM TB_LMS_SBJCT WHERE SBJCT_ID = A.SBJCT_ID) AS SBJCTNM , (SELECT DVCLAS_NO FROM TB_LMS_SBJCT WHERE SBJCT_ID = A.SBJCT_ID) AS DVCLAS_NO FROM TB_LMS_BBS_ATCL A WHERE A.ATCL_ID IN
#{item}
) A ORDER BY (CASE WHEN A.SBJCT_ID = #{crsCreCd} THEN 0 ELSE 1 END), A.SBJCTNM, A.DVCLAS_NO

/* SQL ID : BbsAtclDAO.listRecentAtcl, TOBE: atclList 설 명 : 강의실 홈 최신글, TOBE: 게시글목록조회, 과목과관련있는 게시글목록조회로 추정 */
SELECT A.* , 'Y' IS_NEW -- CASE WHEN A.REG_DTTM > FN_DTTM_SUB(7) THEN 'Y' ELSE 'N' END AS IS_NEW , 'Y' ANSWER_YN --CASE WHEN EXISTS (SELECT 1 FROM TB_LMS_BBS_ATCL WHERE UP_ATCL_ID = A.ATCL_ID AND DELYN = 'N') THEN 'Y' ELSE 'N' END AS ANSWER_YN , 'Y' INQYN -- , CASE WHEN EXISTS(SELECT 1 FROM TB_LMS_BBS_ATCL_INQ_RCD WHERE ATCL_ID = A.ATCL_ID AND USER_ID = 'USR000000002') THEN 'Y' ELSE 'N' END AS INQYN , 'Y' ANS_VIEW_YN , C.DVCLAS_NO , C.SBJCTNM FROM TB_LMS_BBS_ATCL A JOIN TB_LMS_BBS B ON A.BBS_ID = B.BBS_ID AND B.DELYN = 'N' AND b.BBS_TYCD = 'NOTICE' JOIN TB_LMS_SBJCT_OFRNG C ON B.SBJCT_OFRNG_ID = C.SBJCT_OFRNG_ID
AND C.RLTN_REF_CD IN
#{item}
AND B.SBJCT_OFRNG_ID = #{crsCreCd}
WHERE 1 = 1
AND A.UP_ATCL_ID IS NULL
AND A.RGTR_ID = #{userId}
AND ( A.RGTR_ID = #{userId} )
ORDER BY A.REG_DTTM

mapper.sql:
SELECT ROW_NUMBER() OVER(ORDER BY CASE C.OPTN_CD WHEN 'FIX' THEN 1 WHEN 'IMPT' THEN 2 ELSE 3 END, A.REG_DTTM DESC) AS LINE_NO , A.ATCL_ID , A.BBS_ID , B.BBS_TYCD , A.ORG_ID , (SELECT ORGNM FROM TB_LMS_ORG WHERE ORG_ID = A.ORG_ID) AS ORGNM , A.DEPT_ID , (SELECT DEPTNM FROM TB_LMS_DEPT WHERE DEPT_ID = A.DEPT_ID) AS DEPTNM , A.SBJCT_ID , (SELECT SBJCTNM FROM TB_LMS_SBJCT WHERE SBJCT_ID = A.SBJCT_ID) AS SBJCTNM , A.USER_ID , A.UP_ATCL_ID , A.DVCLAS_REG_ATCL_ID , A.ATCL_TTL , A.ATCL_CTS , A.ATCL_HASH_TAG_CTS , A.ATCL_LV , A.ATCL_SEQNO , A.FVRT_CNT , A.REF_CMNT_ID , A.THMB_FILE_ID , A.PROC_STSCD , A.HDR_TYCD , A.ATHR_ID , A.DSCSN_PROF_ID , A.RGTR_ID , A.REG_DTTM , A.MDFR_ID , A.MOD_DTTM , A.DELYN , (SELECT USERNM FROM TB_LMS_USER WHERE USER_ID = A.RGTR_ID) AS RGTRNM , A.OYN , A.RSRVYN , A.RSRV_SDTTM , A.RSRV_EDTTM , A.CMNT_PRMYN , A.NTC_GBNCD , A.AUTO_ALIM_SDTTM , A.AUTO_ALIM_EDTTM , A.SRC_ATCL_ID , A.AUTO_ALIMYN , NVL(TO_CHAR((SELECT DVCLAS_NO FROM TB_LMS_SBJCT WHERE SBJCT_ID = A.SBJCT_ID)), '-') AS DVCLAS_NO , C.ATCL_OPTN_ID , C.OPTN_CD , C.OPTN_USEYN , C.OPTN_SDTTM , C.OPTN_EDTTM , CASE WHEN A.REG_DTTM > FN_DTTM_SUB(7) THEN 'Y' ELSE 'N' END AS IS_NEW , ( SELECT COUNT(1) FROM TB_LMS_BBS_ATCL_CMNT WHERE ATCL_ID = A.ATCL_ID AND (UP_ATCL_CMNT_ID IS NULL OR UP_ATCL_CMNT_ID = '0' OR UP_ATCL_CMNT_ID = '') AND DELYN = 'N' ) AS CMNT_CNT , CASE WHEN EXISTS ( SELECT 1 FROM TB_LMS_BBS_ATCL WHERE UP_ATCL_ID = A.ATCL_ID AND DELYN = 'N' ) THEN 'Y' ELSE 'N' END AS ANSWER_YN , FN_REF_FILE_CNT(A.ATCL_ID) AS FILE_CNT , COUNT(*) OVER() AS TOTAL_CNT , (SELECT TEAM_GRPNM FROM TB_LMS_TEAM_GRP WHERE TEAM_GRP_ID = A.TEAM_GRP_ID) AS TEAM_GRPNM , (SELECT TEAMNM FROM TB_LMS_TEAM WHERE TEAM_ID = A.LRN_TEAM_ID) AS TEAMNM /* TOBE - by jinkoon 20260623 */ , (SELECT COUNT(ATCL_ID) FROM TB_LMS_BBS_ATCL_INQ_RCD WHERE ATCL_ID = A.ATCL_ID) AS INQ_CNT /* ASIS , (SELECT SUM(INQ_CNT) FROM TB_LMS_BBS_ATCL_INQ_RCD WHERE ATCL_ID = A.ATCL_ID) AS INQ_CNT */ FROM TB_LMS_BBS_ATCL A JOIN TB_LMS_BBS B ON A.BBS_ID = B.BBS_ID LEFT JOIN TB_LMS_BBS_ATCL_OPTN C ON A.ATCL_ID = C.ATCL_ID WHERE 1=1
AND B.ORG_ID = #{orgId}
AND ( ( B.BBS_TYCD = #{bbsTycd}
) OR B.BBS_TYCD = 'SYS_NTC' )
AND B.BBS_TYCD = #{bbsTycd}
AND ( A.BBS_ID = #{bbsId} OR A.BBS_ID = #{orgId} || '_' || #{bbsTycd} )
AND ( A.BBS_ID = #{bbsId} OR A.BBS_ID = #{orgId} || '_' || #{bbsTycd} || '_' || #{bbsRefTycd} )
AND ( A.BBS_ID = #{bbsId}
OR A.BBS_ID = ( SELECT SUB.BBS_ID FROM TB_LMS_BBS SUB WHERE SUB.SBJCT_ID = #{sbjctId} AND ROWNUM = 1 )
)
AND A.ATCL_LV = #{atclLv}
AND A.UP_ATCL_ID = #{upAtclId}
AND A.REG_DTTM >= REPLACE(#{searchSdttm}, '-', '') || '000000'
AND A.REG_DTTM <= REPLACE(#{searchEdttm}, '-', '') || '235959'
AND (A.SBJCT_ID = #{sbjctId} OR A.SBJCT_ID IS NULL)
AND A.RGTR_ID = #{rgtrId}
AND LOWER(A.ATCL_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
AND LOWER(A.RGTRNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
AND ( LOWER(A.ATCL_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(A.RGTRNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
AND ( A.SBJCT_ID IS NULL OR A.SBJCT_ID IN ( SELECT SUB.SBJCT_ID FROM TB_LMS_SBJCT SUB JOIN TB_LMS_SBJCT_ADM ADM ON SUB.SBJCT_ID = ADM.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SMT ON SUB.SMSTR_CHRT_ID = SMT.SMSTR_CHRT_ID WHERE ADM.USER_ID = #{vwerId} AND SUB.DELYN = 'N'
AND SMT.ORG_ID = #{orgId}
) )
AND A.DELYN = 'N' ORDER BY CASE C.OPTN_CD WHEN 'FIX' THEN 1 WHEN 'IMPT' THEN 2 ELSE 3 END, A.REG_DTTM DESC

SELECT A.ATCL_ID , B.ORG_ID , A.BBS_ID , A.USER_ID , A.UP_ATCL_ID , A.ATCL_TTL , A.ATCL_CTS , A.ATCL_LV , A.ATCL_SEQNO , C.ATCL_CMNT_ID , C.UP_ATCL_CMNT_ID , C.ATCL_CMNT_CTS , C.EMTICN_NO FROM TB_LMS_BBS_ATCL A JOIN TB_LMS_BBS B ON A.BBS_ID = B.BBS_ID JOIN TB_LMS_BBS_ATCL_CMNT C ON A.ATCL_ID = C.ATCL_ID WHERE 1=1 AND A.BBS_ID = #{bbsId} AND A.DELYN = 'N' AND A.ATCL_ID = #{atclId}
AND B.ORG_ID = #{orgId}
AND A.BBS_ID IN (
#{item}
)
AND B.SBJCT_OFRNG_ID = #{sbjctOfrngId}
AND LOWER(A.ATCL_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
AND LOWER(A.RGTRNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
AND ( LOWER(A.ATCL_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(A.RGTRNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
ORDER BY A.REG_DTTM DESC

mapper.insert:
		/*
             SQL ID : BbsAtclDAO.insertBbsAtcl
             설  명 : 게시글 정보 저장
         */
		MERGE INTO TB_LMS_BBS_ATCL A
		USING DUAL
		ON (A.ATCL_ID = #{atclId})
		WHEN MATCHED THEN
		    UPDATE SET
		          ATCL_TTL         = #{atclTtl}
		        , ATCL_CTS         = #{atclCts}
		        , ATCL_HASH_TAG_CTS = #{atclHashTagCts}
		        , THMB_FILE_ID     = #{thmbFileId}
		        , HDR_TYCD         = #{hdrTycd}
		        , MDFR_ID          = #{mdfrId}
		        , MOD_DTTM         = FN_DTTM()
		WHEN NOT MATCHED THEN
		    INSERT (
		          ATCL_ID, BBS_ID, USER_ID, UP_ATCL_ID, DVCLAS_REG_ATCL_ID
		        , ATCL_TTL, ATCL_CTS, ATCL_HASH_TAG_CTS, ATCL_LV, ATCL_SEQNO
		        , FVRT_CNT, INQ_CNT, REF_CMNT_ID, THMB_FILE_ID, PROC_STSCD
		        , HDR_TYCD, ATHR_ID, DSCSN_PROF_ID, RGTR_ID, REG_DTTM
		        , MDFR_ID, MOD_DTTM, DELYN, RGTRNM, NTC_GBNCD
		    ) VALUES (
		          #{atclId}
		        , #{bbsId}
		        , #{userId}
		        , #{upAtclId}
		        , #{dvclasRegAtclId}
		        , #{atclTtl}
		        , #{atclCts}
		        , #{atclHashTagCts}
		        , 1
		        , NVL((SELECT MAX(NVL(B.ATCL_SEQNO, 0)) + 1 FROM TB_LMS_BBS_ATCL B WHERE B.BBS_ID = #{bbsId}), 1)
		        , 0
		        , 0
		        , #{refCmntId}
		        , #{thmbFileId}
		        , 'S'
		        , #{hdrTycd}
		        , #{athrId}
		        , #{dscsnProfId}
		        , #{rgtrId}
		        , FN_DTTM()
		        , #{mdfrId}
		        , FN_DTTM()
		        , 'N'
		        , #{rgtrnm}
		        , #{bbsRefTycd}
		    )

mapper.update:
		/*
        	SQL ID : BbsAtclDAO.updateBbsAtcl
        	설  명 : 게시판게시글 수정
         */
		MERGE INTO TB_LMS_BBS_ATCL A
		USING DUAL
		   ON (A.ATCL_ID = #{atclId})
		 WHEN MATCHED THEN
		    UPDATE SET
		    	  A.ATCL_TTL    = #{atclTtl}
		        , A.ATCL_CTS    = #{atclCts}
		        , A.DVCLAS_NO   = #{dvclasNo}
		        , A.OYN         = #{oyn}
		        , A.RSRVYN      = #{rsrvyn}
		        , A.RSRV_SDTTM  = #{rsrvSdttm}
		        , A.RSRV_EDTTM  = #{rsrvEdttm}
		        , A.CMNT_PRMYN  = #{cmntPrmyn}
		        , A.AUTO_ALIMYN  = #{autoAlimyn}
		        , A.AUTO_ALIM_SDTTM  = #{autoAlimSdttm}
		        , A.AUTO_ALIM_EDTTM  = #{autoAlimEdttm}
		        , A.MDFR_ID      = #{rgtrId}
		        , A.MOD_DTTM     = FN_DTTM()
		 WHEN NOT MATCHED THEN
		    INSERT (
		    	ORG_ID
				, SBJCT_ID
		        , ATCL_ID
		        , USER_ID
		        , UP_ATCL_ID
		        , BBS_ID
		        , ATCL_TTL
		        , ATCL_CTS
		        , ATCL_LV
		        , FVRT_CNT
		        , INQ_CNT
		        , PROC_STSCD
		        , RGTRNM
		        , DVCLAS_NO
		        , CMNT_PRMYN
		        , RSRVYN
		        , RSRV_SDTTM
		        , RSRV_EDTTM
		        , OYN
		        , NTC_GBNCD
		        , AUTO_ALIMYN
		        , AUTO_ALIM_SDTTM
		        , AUTO_ALIM_EDTTM
		        , RGTR_ID
		        , REG_DTTM
		    ) VALUES (
		        #{orgId}
		        , #{sbjctId}
		        , #{atclId}
		        , #{userId}
		        , #{upAtclId}
		        , #{bbsId}
		        , #{atclTtl}
		        , #{atclCts}
		        , 1
		        , 0
		        , 0
		        , 'S'
		        , #{rgtrnm}
		        , #{dvclasNo}
		        , #{cmntPrmyn}
		        , #{rsrvyn}
		        , #{rsrvSdttm}
		        , #{rsrvEdttm}
		        , #{oyn}
		        , #{ntcGbncd}
		        , #{autoAlimyn}
		        , #{autoAlimSdttm}
		        , #{autoAlimEdttm}
		        , #{rgtrId}
		        , FN_DTTM()
		    )

