mapper.select:
/* SQL ID : BbsAtclDAO.selectBbsAtclRspnsList 설 명 : 게시판 답변 목록 조회 (페이징) */
SELECT A.ATCL_ID , D.ATCL_OPTN_ID , D.OPTN_CD , D.OPTN_USEYN , D.OPTN_SDTTM , D.OPTN_EDTTM , A.BBS_ID , B.BBS_TYCD , C.SBJCT_ID , (SELECT ORGNM FROM TB_LMS_ORG WHERE ORG_ID = A.ORG_ID) AS ORGNM , (SELECT SBJCTNM FROM TB_LMS_SBJCT WHERE SBJCT_ID = A.SBJCT_ID) AS SBJCTNM , C.DVCLAS_NO , A.USER_ID , A.UP_ATCL_ID , A.DVCLAS_REG_ATCL_ID , A.ATCL_TTL , A.ATCL_CTS , A.ATCL_HASH_TAG_CTS , A.ATCL_LV , A.ATCL_SEQNO , A.FVRT_CNT , A.INQ_CNT , A.REF_CMNT_ID , A.THMB_FILE_ID , A.PROC_STSCD , A.HDR_TYCD , A.ATHR_ID , A.DSCSN_PROF_ID , A.RGTR_ID , A.REG_DTTM , A.MDFR_ID , A.MOD_DTTM , A.DELYN , A.OYN , A.RSRVYN , A.RSRV_SDTTM , A.RSRV_EDTTM , A.CMNT_PRMYN , A.NTC_GBNCD , A.AUTO_ALIM_SDTTM , A.AUTO_ALIM_EDTTM , (SELECT USERNM FROM TB_LMS_USER WHERE USER_ID = A.USER_ID) AS RGTRNM , CASE WHEN A.REG_DTTM > FN_DTTM_SUB(7) THEN 'Y' ELSE 'N' END AS IS_NEW , (SELECT COUNT(1) FROM TB_LMS_BBS_ATCL_CMNT XX WHERE XX.ATCL_ID IN (SELECT UP_ATCL_ID FROM TB_LMS_BBS_ATCL WHERE UP_ATCL_ID = A.ATCL_ID)) AS CMNT_CNT , ROW_NUMBER() OVER(ORDER BY A.REG_DTTM DESC) AS LINE_NO , COUNT(*) OVER() AS TOTAL_CNT , FN_REF_FILE_CNT(A.ATCL_ID) AS FILE_CNT FROM TB_LMS_BBS_ATCL A JOIN TB_LMS_BBS B ON A.BBS_ID = B.BBS_ID JOIN TB_LMS_SBJCT C ON C.SBJCT_ID = B.SBJCT_ID LEFT JOIN TB_LMS_BBS_ATCL_OPTN D ON A.ATCL_ID = D.ATCL_ID WHERE 1=1 AND A.BBS_ID = #{bbsId} AND A.ATCL_LV = #{atclLv} AND A.DELYN = 'N'
AND A.ATCL_ID = #{atclId}
AND A.UP_ATCL_ID = #{upAtclId}
AND C.SBJCT_YR = #{sbjctYr}
AND C.SBJCT_SMSTR = #{sbjctSmstr}
AND B.ORG_ID = #{orgId}
AND C.SBJCT_ID = #{sbjctId}
AND ( LOWER(A.ATCL_TTL) LIKE LOWER('%' || #{searchValue} || '%') OR LOWER(( SELECT USERNM FROM TB_LMS_USER WHERE USER_RPRS_ID = A.USER_ID )) LIKE LOWER('%' || #{searchValue} || '%') )
ORDER BY A.REG_DTTM DESC

mapper.insert:
		/*
             SQL ID : BbsAtclDAO.bbsAtclSbjctRegist
             설  명 : 게시글 > 과목 공지 > 글쓰기 저장
         */
	    MERGE INTO TB_LMS_BBS_ATCL A
		USING DUAL
		   ON (A.ATCL_ID = #{atclId})
		 WHEN MATCHED THEN
		    UPDATE SET
		    	  A.ORG_ID      = #{orgId}
		    	, A.SBJCT_ID    = #{sbjctId}
		    	, A.TEAM_GRP_ID = #{teamGrpId}
		    	, A.LRN_TEAM_ID = #{lrnTeamId}
		        , A.ATCL_TTL    = #{atclTtl}
		        , A.ATCL_CTS    = #{atclCts}
		        , A.RGTRNM      = #{rgtrnm}
		        , A.DVCLAS_NO   = #{dvclasNo}
		        , A.OYN         = #{oyn}
		        , A.NTC_GBNCD   = #{ntcGbncd}
		        , A.RSRVYN      = #{rsrvyn}
		        , A.RSRV_SDTTM  = #{rsrvSdttm}
		        , A.RSRV_EDTTM  = #{rsrvEdttm}
		        , A.CMNT_PRMYN  = #{cmntPrmyn}
		        , A.AUTO_ALIMYN  = #{autoAlimyn}
		        , A.AUTO_ALIM_SDTTM  = #{autoAlimSdttm}
		        , A.AUTO_ALIM_EDTTM  = #{autoAlimEdttm}
		        , A.MDFR_ID      = #{rgtrId}
		        , A.MOD_DTTM     = FN_DTTM()
		 WHEN NOT MATCHED THEN
		    INSERT (
		    	ORG_ID
				, SBJCT_ID
				, TEAM_GRP_ID
				, LRN_TEAM_ID
		        , ATCL_ID
		        , USER_ID
		        , UP_ATCL_ID
		        , BBS_ID
		        , ATCL_TTL
		        , ATCL_CTS
		        , ATCL_LV
		        , FVRT_CNT
		        , INQ_CNT
		        , PROC_STSCD
		        , RGTRNM
		        , DVCLAS_NO
		        , CMNT_PRMYN
		        , RSRVYN
		        , RSRV_SDTTM
		        , RSRV_EDTTM
		        , OYN
		        , NTC_GBNCD
		        , AUTO_ALIMYN
		        , AUTO_ALIM_SDTTM
		        , AUTO_ALIM_EDTTM
		        , RGTR_ID
		        , REG_DTTM
		    ) VALUES (
		        #{orgId}
		        , #{sbjctId}
		        , #{teamGrpId}
		        , #{lrnTeamId}
		        , #{atclId}
		        , #{userId}
		        , #{upAtclId}
		        , #{bbsId}
		        , #{atclTtl}
		        , #{atclCts}
		        , 1
		        , 0
		        , 0
		        , 'S'
		        , #{rgtrnm}
		        , #{dvclasNo}
		        , #{cmntPrmyn}
		        , #{rsrvyn}
		        , #{rsrvSdttm}
		        , #{rsrvEdttm}
		        , #{oyn}
		        , #{ntcGbncd}
		        , #{autoAlimyn}
		        , #{autoAlimSdttm}
		        , #{autoAlimEdttm}
		        , #{rgtrId}
		        , FN_DTTM()
		    )

/* SQL ID : BbsAtclDAO.bbsGrpNtcRegist 설 명 : 게시글 > 과목 공지 > 글쓰기 저장 */ INSERT INTO TB_LMS_BBS_GRP_NTC_TRGTR ( BBS_GRP_NTC_TRGTR_ID, ATCL_ID, DEPT_ID, SBJCT_ID, USER_ID, RGTR_ID, REG_DTTM ) SELECT FN_NEW_ID('BGNT') , X.ATCL_ID , X.DEPT_ID , X.SBJCT_ID , X.USER_ID , X.RGTR_ID , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') FROM (
SELECT #{atclId} AS ATCL_ID , #{u.deptId} AS DEPT_ID , #{sbjctId} AS SBJCT_ID , #{u.userId} AS USER_ID , #{rgtrId} AS RGTR_ID FROM DUAL
) X

mapper.select:
/* SQL ID : BbsAtclDAO.bbsTeamMbrListView 설 명 : 팀 게시판 > 팀 구성원 */
SELECT ROW_NUMBER() OVER(ORDER BY T.TEAM_ID) AS LINE_NO , T.TEAM_GRP_ID , T.TEAM_ID , M.TEAM_MBR_ID , M.USER_ID , (SELECT USERNM FROM TB_LMS_USER WHERE USER_ID = M.USER_ID) AS USERNM , M.ROLE , M.LDRYN , M.RGTR_ID , M.REG_DTTM , M.MDFR_ID , M.MOD_DTTM FROM TB_LMS_TEAM T JOIN TB_LMS_TEAM_MBR M ON M.TEAM_ID = T.TEAM_ID WHERE 1 = 1
AND T.TEAM_GRP_ID = #{teamGrpId}
AND T.TEAM_ID = #{lrnTeamId}

/* SQL ID : BbsAtclDAO.bbsGrpNtcStdntAtndList 설 명 : 수강생 출석 미달자 정보 목록 페이징 */
SELECT ROW_NUMBER() OVER(ORDER BY A.REG_DTTM) AS LINE_NO , A.USER_ID , U.USERNM , U.DEPT_ID , (SELECT DEPTNM FROM TB_LMS_DEPT WHERE DEPT_ID = U.DEPT_ID) AS DEPTNM , S.SBJCT_ID , S.LCTR_WKNO , S.LCTR_WKNO_CD , S.LCTR_WKNONM , A.PRGRT , C.LRN_PRD_IN_PRGRT , A.LRN_STSCD , A.RCNT_LRN_DTTM FROM TB_LMS_BYWKNO_USER_LRN_STS A JOIN TB_LMS_LCTR_WKNO_SCHDL S ON S.LCTR_WKNO_SCHDL_ID = A.LCTR_WKNO_SCHDL_ID AND S.DELYN = 'N' JOIN TB_LMS_BYWKNO_ATTNDNC_CRTR C ON C.SBJCT_ID = S.SBJCT_ID LEFT JOIN TB_LMS_USER U ON U.USER_ID = A.USER_ID WHERE A.PRGRT < C.LRN_PRD_IN_PRGRT AND S.LCTR_WKNO_SCHDL_ID = #{lctrWknoSchdlId}
AND ( LOWER(U.USER_ID) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(U.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
ORDER BY S.SBJCT_ID, A.USER_ID, S.LCTR_WKNO

/* SQL ID : BbsAtclDAO.bbsGrpNtcStdntAtndList 설 명 : 수강생 정보 목록 페이징 */ SELECT ROW_NUMBER() OVER (ORDER BY TEAM.TEAM_ID DESC) AS LINE_NO , GRP.TEAM_GRP_ID AS TEAM_GRP_ID , GRP.TEAM_GRPNM AS TEAM_GRPNM , TEAM.TEAM_ID AS TEAM_ID , TEAM.TEAMNM AS TEAMNM , TEAM.TEAM_BBS_USEYN AS TEAM_BBS_USEYN , MBR.USER_ID AS USER_ID , MBR.LDRYN AS LDRYN , USR.USERNM AS USERNM , USR.USER_RPRS_ID AS USER_RPRS_ID , USR.STDNT_NO AS STDNT_NO , DEPT.DEPTNM AS DEPTNM , DEPT.DEPT_ID AS DEPT_ID FROM TB_LMS_TEAM_GRP GRP JOIN TB_LMS_TEAM TEAM ON GRP.TEAM_GRP_ID = TEAM.TEAM_GRP_ID JOIN TB_LMS_TEAM_MBR MBR ON TEAM.TEAM_ID = MBR.TEAM_ID JOIN TB_LMS_USER USR ON MBR.USER_ID = USR.USER_ID JOIN TB_LMS_DEPT DEPT ON USR.DEPT_ID = DEPT.DEPT_ID WHERE 1=1 AND GRP.SBJCT_ID = #{sbjctId}
AND GRP.TEAM_GRP_ID = #{teamGrpId}
AND TEAM.TEAM_ID = #{lrnTeamId}
AND ( LOWER(USR.STDNT_NO) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(USR.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )

mapper.delete:
		/*
             SQL ID : BbsInfoDAO.deleteBbsGrpNtcTrgtr
             설  명 : 게시판 > 그룹 공지사항 삭제
         */
		DELETE FROM TB_LMS_BBS_GRP_NTC_TRGTR
		WHERE ATCL_ID = #{atclId}
